solutionCode:
def character_replacement(s, k):
    counts = {}
    best = 0
    top = 0
    left = 0
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        if counts[ch] > top:
            top = counts[ch]
        while right - left + 1 - top > k:
            counts[s[left]] -= 1
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    return best

bruteForceCode:
def character_replacement(s, k):
    best = 0
    for i in range(len(s)):
        counts = {}
        for j in range(i, len(s)):
            counts[s[j]] = counts.get(s[j], 0) + 1
            top = max(counts.values())
            if j - i + 1 - top <= k and j - i + 1 > best:
                best = j - i + 1
    return best
